module.exports = "import React, {\n  Component,\n} from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\n\nimport {\n  EuiBasicTable,\n  EuiHealth,\n  EuiIcon,\n  EuiLink,\n  EuiToolTip,\n} from '../../../../../src/components';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport class Table extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      pageIndex: 0,\n      pageSize: 5,\n      sortField: 'firstName',\n      sortDirection: 'asc',\n    };\n  }\n\n  onTableChange = ({ page = {}, sort = {} }) => {\n    const {\n      index: pageIndex,\n      size: pageSize,\n    } = page;\n\n    const {\n      field: sortField,\n      direction: sortDirection,\n    } = sort;\n\n    this.setState({\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n    });\n  };\n\n  render() {\n    const {\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n    } = this.state;\n\n    const {\n      pageOfItems,\n      totalItemCount,\n    } = store.findUsers(pageIndex, pageSize, sortField, sortDirection);\n\n    const columns = [{\n      field: 'firstName',\n      name: 'First Name',\n      sortable: true,\n      truncateText: true,\n      mobileOptions: {\n        render: (item) => (\n          <span>{item.firstName} {item.lastName}</span>\n        ),\n        header: false,\n        truncateText: false,\n        enlarge: true,\n        fullWidth: true,\n      }\n    }, {\n      field: 'lastName',\n      name: 'Last Name',\n      sortable: true,\n      truncateText: true,\n      mobileOptions: {\n        show: false,\n      }\n    }, {\n      field: 'github',\n      name: (\n        <EuiToolTip content=\"Their mascot is the Octokitty\">\n          <span>\n            Github <EuiIcon size=\"s\" color=\"subdued\" type=\"questionInCircle\" className=\"eui-alignTop\" />\n          </span>\n        </EuiToolTip>\n      ),\n      sortable: true,\n      render: (username) => (\n        <EuiLink href={`https://github.com/${username}`} target=\"_blank\">\n          {username}\n        </EuiLink>\n      )\n    }, {\n      field: 'dateOfBirth',\n      name: (\n        <EuiToolTip content=\"Colloquially known as a 'birthday'\">\n          <span>\n            Date of Birth <EuiIcon size=\"s\" color=\"subdued\" type=\"questionInCircle\" className=\"eui-alignTop\" />\n          </span>\n        </EuiToolTip>\n      ),\n      dataType: 'date',\n      render: (date) => formatDate(date, 'dobLong'),\n      sortable: true\n    }, {\n      field: 'nationality',\n      name: (\n        <EuiToolTip content=\"The nation in which this person resides\">\n          <span>\n            Nationality <EuiIcon size=\"s\" color=\"subdued\" type=\"questionInCircle\" className=\"eui-alignTop\" />\n          </span>\n        </EuiToolTip>\n      ),\n      sortable: true,\n      render: (countryCode) => {\n        const country = store.getCountry(countryCode);\n        return `${country.flag} ${country.name}`;\n      }\n    }, {\n      field: 'online',\n      name: (\n        <EuiToolTip content=\"Free to talk or busy with business\">\n          <span>\n            Online <EuiIcon size=\"s\" color=\"subdued\" type=\"questionInCircle\" className=\"eui-alignTop\" />\n          </span>\n        </EuiToolTip>\n      ),\n      dataType: 'boolean',\n      sortable: true,\n      render: (online) => {\n        const color = online ? 'success' : 'danger';\n        const label = online ? 'Online' : 'Offline';\n        return <EuiHealth color={color}>{label}</EuiHealth>;\n      },\n      sortable: true\n    }];\n\n    const pagination = {\n      pageIndex: pageIndex,\n      pageSize: pageSize,\n      totalItemCount: totalItemCount,\n      pageSizeOptions: [3, 5, 8]\n    };\n\n    const sorting = {\n      sort: {\n        field: sortField,\n        direction: sortDirection,\n      },\n    };\n\n    return (\n      <div>\n        <EuiBasicTable\n          items={pageOfItems}\n          columns={columns}\n          pagination={pagination}\n          sorting={sorting}\n          onChange={this.onTableChange}\n        />\n      </div>\n    );\n  }\n}\n"