module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiDualRange,\n} from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      value: ['', ''],\n    };\n  }\n\n  onChange = (value) => {\n    this.setState({\n      value\n    });\n  };\n\n  render() {\n    return (\n      <EuiDualRange\n        id={makeId()}\n        min={-100}\n        max={200}\n        step={10}\n        value={this.state.value}\n        onChange={this.onChange}\n        showLabels\n      />\n    );\n  }\n}\n"