module.exports = "import React, {\n  Component,\n  Fragment,\n} from 'react';\n\nimport {\n  EuiCode,\n  EuiFieldText,\n  EuiForm,\n  EuiFormRow,\n  EuiDescribedFormGroup,\n  EuiFilePicker,\n  EuiRange,\n  EuiSelect,\n  EuiSwitch,\n} from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    const idPrefix = makeId();\n\n    this.state = {\n      isSwitchChecked: false,\n      checkboxes: [{\n        id: `${idPrefix}0`,\n        label: 'Option one',\n      }, {\n        id: `${idPrefix}1`,\n        label: 'Option two is checked by default',\n      }, {\n        id: `${idPrefix}2`,\n        label: 'Option three',\n      }],\n      checkboxIdToSelectedMap: {\n        [`${idPrefix}1`]: true,\n      },\n      radios: [{\n        id: `${idPrefix}4`,\n        label: 'Option one',\n      }, {\n        id: `${idPrefix}5`,\n        label: 'Option two is selected by default',\n      }, {\n        id: `${idPrefix}6`,\n        label: 'Option three',\n      }],\n      radioIdSelected: `${idPrefix}5`,\n    };\n  }\n\n  onSwitchChange = () => {\n    this.setState({\n      isSwitchChecked: !this.state.isSwitchChecked,\n    });\n  }\n\n  onCheckboxChange = optionId => {\n    const newCheckboxIdToSelectedMap = ({ ...this.state.checkboxIdToSelectedMap, ...{\n      [optionId]: !this.state.checkboxIdToSelectedMap[optionId],\n    } });\n\n    this.setState({\n      checkboxIdToSelectedMap: newCheckboxIdToSelectedMap,\n    });\n  }\n\n  onRadioChange = optionId => {\n    this.setState({\n      radioIdSelected: optionId,\n    });\n  }\n\n  render() {\n    return (\n      <EuiForm>\n        <EuiDescribedFormGroup\n          idAria=\"single-example-aria\"\n          title={<h3>Single text field</h3>}\n          description={\n            <Fragment>\n              When using this with a single form row where this text serves as the help text for the input,\n              it is a good idea to pass <EuiCode>idAria=&quot;someID&quot;</EuiCode> to the form group and pass\n              <EuiCode>describedByIds=&#123;[someID]&#125;</EuiCode> to its form row.\n            </Fragment>\n          }\n        >\n          <EuiFormRow\n            label=\"Text field\"\n            describedByIds={['single-example-aria']}\n          >\n            <EuiFieldText name=\"first\" />\n          </EuiFormRow>\n        </EuiDescribedFormGroup>\n\n        <EuiDescribedFormGroup\n          idAria=\"no-description\"\n          title={<h3>No description</h3>}\n        >\n          <EuiFormRow\n            label=\"Text field\"\n            describedByIds={['no-description']}\n          >\n            <EuiFieldText name=\"first\" />\n          </EuiFormRow>\n        </EuiDescribedFormGroup>\n\n        <EuiDescribedFormGroup\n          title={<strong>Multiple fields</strong>}\n          titleSize=\"m\"\n          description=\"Here are three form rows. The first form row does not have a title.\"\n        >\n          <EuiFormRow\n            hasEmptyLabelSpace\n            helpText={\n              <span>\n                We do not pass <EuiCode>describedByIds</EuiCode> when there are multiple form rows.\n              </span>\n            }\n          >\n            <EuiSelect\n              hasNoInitialSelection\n              options={[\n                { value: 'option_one', text: 'Option one' },\n                { value: 'option_two', text: 'Option two' },\n                { value: 'option_three', text: 'Option three' },\n              ]}\n            />\n          </EuiFormRow>\n\n          <EuiFormRow\n            label=\"File picker\"\n          >\n            <EuiFilePicker />\n          </EuiFormRow>\n\n          <EuiFormRow\n            label=\"Range\"\n          >\n            <EuiRange\n              min={0}\n              max={100}\n              name=\"range\"\n              id=\"range\"\n            />\n          </EuiFormRow>\n        </EuiDescribedFormGroup>\n\n        <EuiDescribedFormGroup\n          title={<h2>Full width</h2>}\n          titleSize=\"xxxs\"\n          description={\n            <Fragment>\n              By default, <EuiCode>EuiDescribedFormGroup</EuiCode> will be double the default width of form elements.\n              However, you can pass <EuiCode>fullWidth</EuiCode> prop to this, the individual field and row components\n              to expand to their container.\n            </Fragment>\n          }\n          fullWidth\n        >\n          <EuiFormRow\n            label=\"Use a switch instead of a single checkbox\"\n            fullWidth\n          >\n            <EuiSwitch\n              name=\"switch\"\n              label=\"Should we do this?\"\n              checked={this.state.isSwitchChecked}\n              onChange={this.onSwitchChange}\n            />\n          </EuiFormRow>\n\n          <EuiFormRow fullWidth>\n            <EuiFieldText name=\"second\" fullWidth />\n          </EuiFormRow>\n        </EuiDescribedFormGroup>\n      </EuiForm>\n    );\n  }\n}\n"