module.exports = "\nimport React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiBottomBar,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiButton,\n  EuiButtonEmpty,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      showBar: false,\n    };\n  }\n\n  onButtonClick() {\n    this.setState({\n      showBar: !this.state.showBar,\n    });\n  }\n\n  render() {\n    const button = (\n      <EuiButton color=\"primary\" onClick={this.onButtonClick.bind(this)}>\n        Toggle appearance of the bottom bar\n      </EuiButton>\n    );\n\n    let bottomBar;\n    if (this.state.showBar) {\n      bottomBar = (\n        <EuiBottomBar>\n          <EuiFlexGroup justifyContent=\"spaceBetween\">\n            <EuiFlexItem grow={false}>\n              <EuiFlexGroup gutterSize=\"s\">\n                <EuiFlexItem grow={false}>\n                  <EuiButton color=\"ghost\" size=\"s\" iconType=\"help\">Help</EuiButton>\n                </EuiFlexItem>\n                <EuiFlexItem grow={false}>\n                  <EuiButton color=\"ghost\" size=\"s\" iconType=\"user\">Add user</EuiButton>\n                </EuiFlexItem>\n              </EuiFlexGroup>\n            </EuiFlexItem>\n            <EuiFlexItem grow={false}>\n              <EuiFlexGroup gutterSize=\"s\">\n                <EuiFlexItem grow={false}>\n                  <EuiButtonEmpty color=\"ghost\" size=\"s\" iconType=\"cross\">Discard</EuiButtonEmpty>\n                </EuiFlexItem>\n                <EuiFlexItem grow={false}>\n                  <EuiButton color=\"primary\" fill size=\"s\" iconType=\"check\">Save</EuiButton>\n                </EuiFlexItem>\n              </EuiFlexGroup>\n            </EuiFlexItem>\n          </EuiFlexGroup>\n        </EuiBottomBar>\n\n      );\n    }\n\n    return (\n      <div>\n        {button}\n        {bottomBar}\n      </div>\n    );\n  }\n}\n"