module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiButton,\n  EuiContextMenu,\n  EuiIcon,\n  EuiPopover,\n  EuiSpacer,\n  EuiText\n} from '../../../../src/components';\n\nimport EuiTabsExample from '../tabs/tabbed_content';\n\nfunction flattenPanelTree(tree, array = []) {\n  array.push(tree);\n\n  if (tree.items) {\n    tree.items.forEach(item => {\n      if (item.panel) {\n        flattenPanelTree(item.panel, array);\n        item.panel = item.panel.id;\n      }\n    });\n  }\n\n  return array;\n}\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n\n    this.createPanelTree = (Content) => {\n      return flattenPanelTree({\n        id: 0,\n        title: 'View options',\n        items: [{\n          name: 'Show fullscreen',\n          icon: (\n            <EuiIcon\n              type=\"search\"\n              size=\"m\"\n            />\n          ),\n          onClick: () => { this.closePopover(); window.alert('Show fullscreen'); },\n        }, {\n          name: 'See more',\n          icon: 'plusInCircle',\n          panel: {\n            id: 1,\n            width: 400,\n            title: 'See more',\n            content: <Content />\n          },\n        }],\n      });\n    };\n\n    this.panels = this.createPanelTree(() => (\n      <EuiText style={{ padding: 24 }} textAlign=\"center\">\n        <p><EuiIcon type=\"faceHappy\" size=\"xxl\" /></p>\n\n        <h3>Context panels can contain anything</h3>\n        <p>\n          You can stuff just about anything into these panels. Be mindful of size though.\n          This panel is set to 400px and the height will grow as space allows.\n        </p>\n      </EuiText>\n    ));\n\n    this.dynamicPanels = this.createPanelTree(EuiTabsExample);\n  }\n\n  onButtonClick = () => {\n    this.setState(prevState => ({\n      isPopoverOpen: !prevState.isPopoverOpen,\n    }));\n  };\n\n  onDynamicButtonClick = () => {\n    this.setState(prevState => ({\n      isDynamicPopoverOpen: !prevState.isDynamicPopoverOpen,\n    }));\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  closeDynamicPopover = () => {\n    this.setState({\n      isDynamicPopoverOpen: false,\n    });\n  };\n\n  render() {\n    const button = (\n      <EuiButton\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onButtonClick}\n      >\n        Click me to load mixed content menu\n      </EuiButton>\n    );\n\n    const dynamicButton = (\n      <EuiButton\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onDynamicButtonClick}\n      >\n        Click me to load dynamic mixed content menu\n      </EuiButton>\n    );\n\n    return (\n      <React.Fragment>\n        <EuiPopover\n          id=\"contextMenu\"\n          button={button}\n          isOpen={this.state.isPopoverOpen}\n          closePopover={this.closePopover}\n          panelPaddingSize=\"none\"\n          withTitle\n          anchorPosition=\"upLeft\"\n        >\n          <EuiContextMenu\n            initialPanelId={0}\n            panels={this.panels}\n          />\n        </EuiPopover>\n\n        <EuiSpacer size=\"l\" />\n\n        <EuiPopover\n          id=\"contextMenuDynamic\"\n          button={dynamicButton}\n          isOpen={this.state.isDynamicPopoverOpen}\n          closePopover={this.closeDynamicPopover}\n          panelPaddingSize=\"none\"\n          withTitle\n          anchorPosition=\"upLeft\"\n        >\n          <EuiContextMenu\n            initialPanelId={0}\n            panels={this.dynamicPanels}\n          />\n        </EuiPopover>\n      </React.Fragment>\n    );\n  }\n}\n"