module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiListGroup,\n  EuiSpacer,\n  EuiSwitch,\n  EuiCode,\n  EuiFlexGroup,\n  EuiFlexItem,\n} from '../../../../src/components';\n\nconst myContent = [\n  {\n    label: 'First link',\n    href: '#/display/list-group',\n    iconType: 'calendar',\n    size: 's',\n  },\n  {\n    label: 'This is an active link with very long label that truncates',\n    href: '#/display/list-group',\n    isActive: true,\n    iconType: 'clock',\n    size: 's',\n  },\n  {\n    label: 'Third link is disabled',\n    href: '#/display/list-group',\n    isDisabled: true,\n    iconType: 'compute',\n    size: 's',\n  },\n  {\n    label: 'Fourth link',\n    href: '#/display/list-group',\n    iconType: 'copyClipboard',\n    size: 's',\n  },\n  {\n    label: 'Fifth link',\n    href: '#/display/list-group',\n    iconType: 'crosshairs',\n    size: 's',\n  },\n];\n\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      flushWidth: false,\n      showBorder: false,\n    };\n  }\n\n  toggleFlushWidth = () => {\n    this.setState(prevState => ({ flushWidth: !prevState.flushWidth }));\n  };\n\n  toggleBorder = () => {\n    this.setState(prevState => ({ showBorder: !prevState.showBorder }));\n  };\n\n  render() {\n    const {\n      flushWidth,\n      showBorder,\n    } = this.state;\n\n    return (\n      <Fragment>\n        <EuiFlexGroup alignItems=\"center\">\n          <EuiFlexItem grow={false}>\n            <EuiSwitch\n              label={<span>Show as <EuiCode>flush</EuiCode></span>}\n              checked={this.state.flushWidth}\n              onChange={this.toggleFlushWidth}\n            />\n          </EuiFlexItem>\n          <EuiFlexItem grow={false}>\n            <EuiSwitch\n              label={<span>Show as <EuiCode>bordered</EuiCode></span>}\n              checked={this.state.showBorder}\n              onChange={this.toggleBorder}\n            />\n          </EuiFlexItem>\n        </EuiFlexGroup>\n\n        <EuiSpacer size=\"l\" />\n\n        <EuiListGroup flush={flushWidth} bordered={showBorder} listItems={myContent} />\n      </Fragment>\n    );\n  }\n}\n"