module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport moment from 'moment';\n\nimport {\n  EuiDatePicker,\n  EuiFormRow,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class extends Component {\n\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      startDate: moment()\n    };\n\n    this.handleChange = this.handleChange.bind(this);\n  }\n\n  handleChange(date) {\n    this.setState({\n      startDate: date\n    });\n  }\n\n  render() {\n    return (\n      <div>\n        <EuiFormRow label=\"className example\">\n          <EuiDatePicker\n            selected={this.state.startDate}\n            showTimeSelect\n            onChange={this.handleChange}\n            className=\"dpTest__purpleInput\"\n          />\n        </EuiFormRow>\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFormRow label=\"calendarClassName example\">\n          <EuiDatePicker\n            selected={this.state.startDate}\n            showTimeSelect\n            onChange={this.handleChange}\n            calendarClassName=\"dpTest__purpleCal\"\n          />\n        </EuiFormRow>\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFormRow label=\"dayClassName example\">\n          <EuiDatePicker\n            selected={this.state.startDate}\n            showTimeSelect\n            onChange={this.handleChange}\n            dayClassName={date => date.date() < Math.random() * 31 ? 'dpTest__purpleDay' : undefined}\n          />\n        </EuiFormRow>\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFormRow label=\"popperClassName example\">\n          <EuiDatePicker\n            selected={this.state.startDate}\n            showTimeSelect\n            onChange={this.handleChange}\n            popperClassName=\"dpTest__purplePopper\"\n          />\n        </EuiFormRow>\n\n      </div>\n    );\n  }\n}\n"