module.exports = "\nimport React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiPopover,\n  EuiPopoverTitle,\n  EuiFieldSearch,\n  EuiFilterSelectItem,\n  EuiLoadingChart,\n  EuiSpacer,\n  EuiIcon,\n  EuiFilterGroup,\n  EuiFilterButton,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n      isFilterOn: false,\n      isOnFilterOn: false,\n      isOffFilterOn: false,\n    };\n  }\n\n  toggleFilter = () => {\n    this.setState(prevState => ({\n      isFilterOn: !prevState.isFilterOn,\n    }));\n  }\n\n  toggleOnFilter = () => {\n    this.setState(prevState => ({\n      isOnFilterOn: !prevState.isOnFilterOn,\n      isOffFilterOn: prevState.isOffFilterOn && !prevState.isOnFilterOn ? false : prevState.isOffFilterOn,\n    }));\n  }\n\n  toggleOffFilter = () => {\n    this.setState(prevState => ({\n      isOffFilterOn: !prevState.isOffFilterOn,\n      isOnFilterOn: prevState.isOnFilterOn && !prevState.isOffFilterOn ? false : prevState.isOnFilterOn,\n    }));\n  }\n\n  onButtonClick() {\n    this.setState({\n      isPopoverOpen: !this.state.isPopoverOpen,\n    });\n  }\n\n  closePopover() {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  }\n\n  render() {\n\n    const items = [\n      { name: 'Johann Sebastian Bach', checked: 'on' },\n      { name: 'Wolfgang Amadeus Mozart', checked: 'on' },\n      { name: 'Antonín Dvořák', checked: 'off' },\n      { name: 'Dmitri Shostakovich' },\n      { name: 'Felix Mendelssohn-Bartholdy' },\n      { name: 'Franz Liszt' },\n      { name: 'Franz Schubert' },\n      { name: 'Frédéric Chopin' },\n      { name: 'Georg Friedrich Händel' },\n      { name: 'Giuseppe Verdi' },\n      { name: 'Gustav Mahler' },\n      { name: 'Igor Stravinsky' },\n      { name: 'Johannes Brahms' },\n      { name: 'Joseph Haydn' },\n      { name: 'Ludwig van Beethoven' },\n      { name: 'Piotr Illitch Tchaïkovsky' },\n      { name: 'Robert Schumann' },\n      { name: 'Sergej S. Prokofiew' },\n      { name: 'Wolfgang Amadeus Mozart' },\n    ];\n\n    const button = (\n      <EuiFilterButton\n        iconType=\"arrowDown\"\n        onClick={this.onButtonClick.bind(this)}\n        isSelected={this.state.isPopoverOpen}\n        numFilters={items.length}\n        hasActiveFilters={true}\n        numActiveFilters={2}\n        grow={true}\n      >\n        Composers\n      </EuiFilterButton>\n    );\n\n    return (\n      <EuiFilterGroup>\n        <EuiFilterButton hasActiveFilters={this.state.isFilterOn} onClick={this.toggleFilter}>\n          Filter\n        </EuiFilterButton>\n        <EuiFilterButton noDivider hasActiveFilters={this.state.isOnFilterOn} onClick={this.toggleOnFilter}>\n          On\n        </EuiFilterButton>\n        <EuiFilterButton hasActiveFilters={this.state.isOffFilterOn} onClick={this.toggleOffFilter}>\n          Off\n        </EuiFilterButton>\n        <EuiPopover\n          id=\"popover\"\n          ownFocus\n          button={button}\n          isOpen={this.state.isPopoverOpen}\n          closePopover={this.closePopover.bind(this)}\n          panelPaddingSize=\"none\"\n          withTitle\n        >\n          <EuiPopoverTitle>\n            <EuiFieldSearch />\n          </EuiPopoverTitle>\n          <div className=\"euiFilterSelect__items\">\n            {items.map((item, index) => (\n              <EuiFilterSelectItem\n                checked={item.checked}\n                key={index}\n              >\n                {item.name}\n              </EuiFilterSelectItem>\n            ))}\n            {/*\n              Use when loading items initially\n            */}\n            <div className=\"euiFilterSelect__note\">\n              <div className=\"euiFilterSelect__noteContent\">\n                <EuiLoadingChart size=\"m\" />\n                <EuiSpacer size=\"xs\" />\n                <p>Loading filters</p>\n              </div>\n            </div>\n            {/*\n              Use when no results are returned\n            */}\n            <div className=\"euiFilterSelect__note\">\n              <div className=\"euiFilterSelect__noteContent\">\n                <EuiIcon type=\"minusInCircle\" />\n                <EuiSpacer size=\"xs\" />\n                <p>No filters found</p>\n              </div>\n            </div>\n          </div>\n        </EuiPopover>\n      </EuiFilterGroup>\n    );\n  }\n}\n"