module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiForm,\n  EuiFormRow,\n  EuiSelect,\n  EuiSpacer,\n} from '../../../../src/components';\n\nimport {\n  EuiSeriesChart,\n  EuiAreaSeries,\n} from '../../../../src/experimental';\n\n\nconst DATA_A = [{ x: 0, y: 1 }, { x: 1, y: 1 }, { x: 2, y: 2 }, { x: 3, y: -1 }, { x: 5, y: 2 }];\nconst DATA_B = [{ x: 0, y: 3 }, { x: 1, y: 2 }, { x: 2, y: 4 }, { x: 3, y: 1 }, { x: 5, y: 3 }];\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.options = [\n      { value: 'linear', text: 'Linear' },\n      { value: 'curveCardinal', text: 'Curve Cardinal' },\n      { value: 'curveNatural', text: 'Curve Natural' },\n      { value: 'curveMonotoneX', text: 'Curve Monotone X' },\n      { value: 'curveMonotoneY', text: 'Curve Monotone Y' },\n      { value: 'curveBasis', text: 'Curve Basis' },\n      { value: 'curveCatmullRom', text: 'Curve Catmull Rom' },\n      { value: 'curveStep', text: 'Curve Step' },\n      { value: 'curveStepAfter', text: 'Curve Step After' },\n      { value: 'curveStepBefore', text: 'Curve Step Before' },\n    ];\n\n    this.state = {\n      value: this.options[0].value,\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiForm>\n          <EuiFormRow label=\"Line Mode\">\n            <EuiSelect options={this.options} value={this.state.value} onChange={this.onChange} />\n          </EuiFormRow>\n        </EuiForm>\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiSeriesChart width={600} height={200} stackBy=\"y\">\n          <EuiAreaSeries name=\"Total Bytes A\" data={DATA_A} curve={this.state.value} />\n          <EuiAreaSeries name=\"Total Bytes B\" data={DATA_B} curve={this.state.value} />\n        </EuiSeriesChart>\n      </Fragment>\n    );\n  }\n}\n"