module.exports = "import React from 'react';\n\nimport {\n  EuiFlexGrid,\n  EuiFlexItem,\n  EuiIcon,\n  EuiPanel,\n  EuiText,\n  EuiCallOut,\n  EuiSpacer,\n} from '../../../../src/components';\n\nconst iconColors = [\n  'default',\n  'primary',\n  'secondary',\n  'accent',\n  'warning',\n  'danger',\n  'text',\n  'subdued',\n  'ghost',\n  '#490',\n  '#F98510',\n  '#DDDDDD',\n];\n\nexport default () => (\n  <div>\n    <EuiFlexGrid columns={4}>\n      {\n        iconColors.map(iconColor => (\n          <EuiFlexItem\n            className=\"guideDemo__icon\"\n            key={iconColor}\n            style={{ width: '340px' }}\n          >\n            <EuiPanel>\n              <EuiIcon\n                type=\"brush\"\n                color={iconColor}\n              />\n              <EuiText size=\"s\">\n                <p>{iconColor}</p>\n              </EuiText>\n            </EuiPanel>\n          </EuiFlexItem>\n        ))\n      }\n    </EuiFlexGrid>\n\n    <EuiSpacer />\n\n    <EuiCallOut\n      color=\"warning\"\n      title=\"App icons have special, restricted coloring considerations\"\n      size=\"s\"\n    />\n\n    <EuiSpacer />\n\n    <EuiFlexGrid columns={4}>\n      <EuiFlexItem\n        className=\"guideDemo__icon\"\n        style={{ width: '340px' }}\n      >\n        <EuiPanel>\n          <EuiIcon\n            type=\"gisApp\"\n            size=\"xl\"\n          />\n          <EuiText size=\"s\">\n            <p>Default coloring of <strong>App</strong> icons is two-toned</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n      <EuiFlexItem\n        className=\"guideDemo__icon\"\n        style={{ width: '340px' }}\n      >\n        <EuiPanel>\n          <EuiIcon\n            type=\"gisApp\"\n            color=\"text\"\n            size=\"xl\"\n          />\n          <EuiText size=\"s\">\n            <p><strong>Special:</strong> the text color makes <strong>App</strong> icons fully that color</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n      <EuiFlexItem\n        className=\"guideDemo__icon\"\n        style={{ width: '340px' }}\n      >\n        <EuiPanel>\n          <EuiIcon\n            type=\"createAdvancedJob\"\n            color=\"primary\"\n            size=\"xl\"\n          />\n          <EuiText size=\"s\">\n            <p><strong>Special:</strong> the primary color makes <strong>App</strong> icons fully that color</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n    </EuiFlexGrid>\n  </div>\n);\n"