module.exports = "import React, {\n  Component,\n  Fragment,\n} from 'react';\n\nimport {\n  EuiButtonGroup,\n  EuiSpacer,\n  EuiTitle,\n} from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    const idPrefix = makeId();\n    const idPrefix2 = makeId();\n    const idPrefix3 = makeId();\n\n    this.toggleButtons = [{\n      id: `${idPrefix}0`,\n      label: 'Option one',\n    }, {\n      id: `${idPrefix}1`,\n      label: 'Option two is selected by default',\n    }, {\n      id: `${idPrefix}2`,\n      label: 'Option three',\n    }];\n\n    this.toggleButtonsMulti = [{\n      id: `${idPrefix2}0`,\n      label: 'Option 1',\n    }, {\n      id: `${idPrefix2}1`,\n      label: 'Option 2 is selected by default',\n    }, {\n      id: `${idPrefix2}2`,\n      label: 'Option 3',\n    }];\n\n    this.toggleButtonsIcons = [{\n      id: `${idPrefix3}0`,\n      label: 'Align left',\n      iconType: 'editorAlignLeft',\n    }, {\n      id: `${idPrefix3}1`,\n      label: 'Align center',\n      iconType: 'editorAlignCenter',\n    }, {\n      id: `${idPrefix3}2`,\n      label: 'Align right',\n      iconType: 'editorAlignRight',\n    }];\n\n    this.toggleButtonsIconsMulti = [{\n      id: `${idPrefix3}3`,\n      label: 'Bold',\n      name: 'bold',\n      iconType: 'editorBold',\n    }, {\n      id: `${idPrefix3}4`,\n      label: 'Italic',\n      name: 'italic',\n      iconType: 'editorItalic',\n    }, {\n      id: `${idPrefix3}5`,\n      label: 'Underline',\n      name: 'underline',\n      iconType: 'editorUnderline',\n    }, {\n      id: `${idPrefix3}6`,\n      label: 'Strikethrough',\n      name: 'strikethrough',\n      iconType: 'editorStrike',\n    }];\n\n    this.state = {\n      toggleIdSelected: `${idPrefix}1`,\n      toggleIdToSelectedMap: {\n        [`${idPrefix2}1`]: true,\n      },\n      toggleIconIdSelected: `${idPrefix3}1`,\n      toggleIconIdToSelectedMap: {},\n    };\n  }\n\n  onChange = optionId => {\n    this.setState({\n      toggleIdSelected: optionId,\n    });\n  };\n\n  onChangeMulti = optionId => {\n    const newToggleIdToSelectedMap = ({ ...this.state.toggleIdToSelectedMap, ...{\n      [optionId]: !this.state.toggleIdToSelectedMap[optionId],\n    } });\n\n    this.setState({\n      toggleIdToSelectedMap: newToggleIdToSelectedMap,\n    });\n  };\n\n  onChangeIcons = optionId => {\n    this.setState({\n      toggleIconIdSelected: optionId,\n    });\n  };\n\n  onChangeIconsMulti = optionId => {\n    const newToggleIconIdToSelectedMap = ({ ...this.state.toggleIconIdToSelectedMap, ...{\n      [optionId]: !this.state.toggleIconIdToSelectedMap[optionId],\n    } });\n\n    this.setState({\n      toggleIconIdToSelectedMap: newToggleIconIdToSelectedMap,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiButtonGroup\n          legend=\"This is a basic group\"\n          options={this.toggleButtons}\n          idSelected={this.state.toggleIdSelected}\n          onChange={this.onChange}\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiTitle size=\"xxs\"><h3>Primary &amp; multi select</h3></EuiTitle>\n\n        <EuiSpacer size=\"s\" />\n\n        <EuiButtonGroup\n          legend=\"This is a primary group\"\n          name=\"primary\"\n          options={this.toggleButtonsMulti}\n          idToSelectedMap={this.state.toggleIdToSelectedMap}\n          onChange={this.onChangeMulti}\n          color=\"primary\"\n          type=\"multi\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiTitle size=\"xxs\"><h3>Disabled &amp; full width</h3></EuiTitle>\n\n        <EuiSpacer size=\"s\" />\n\n        <EuiButtonGroup\n          legend=\"This is a disabled group\"\n          name=\"disabledGroup\"\n          options={this.toggleButtons}\n          idSelected={this.state.toggleIdSelected}\n          onChange={this.onChange}\n          isDisabled\n          isFullWidth\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiTitle size=\"xxs\"><h3>Icons only</h3></EuiTitle>\n\n        <EuiSpacer size=\"s\" />\n\n        <EuiButtonGroup\n          legend=\"Text align\"\n          name=\"textAlign\"\n          className=\"eui-displayInlineBlock\"\n          options={this.toggleButtonsIcons}\n          idSelected={this.state.toggleIconIdSelected}\n          onChange={this.onChangeIcons}\n          isIconOnly\n        />\n\n        &nbsp;&nbsp;\n\n        <EuiButtonGroup\n          legend=\"Text style\"\n          className=\"eui-displayInlineBlock\"\n          options={this.toggleButtonsIconsMulti}\n          idToSelectedMap={this.state.toggleIconIdToSelectedMap}\n          onChange={this.onChangeIconsMulti}\n          type=\"multi\"\n          isIconOnly\n        />\n      </Fragment>\n    );\n  }\n}\n"