module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiPage,\n  EuiPageBody,\n  EuiPageHeader,\n  EuiPageHeaderSection,\n  EuiPageContent,\n  EuiPageContentHeader,\n  EuiPageContentHeaderSection,\n  EuiPageContentBody,\n  EuiHeader,\n  EuiHeaderSection,\n  EuiHeaderSectionItem,\n  EuiHeaderSectionItemButton,\n  EuiHeaderBreadcrumbs,\n  EuiHeaderLogo,\n  EuiIcon,\n  EuiTitle,\n  EuiNavDrawer,\n  EuiNavDrawerMenu,\n  EuiNavDrawerFlyout,\n  EuiListGroup,\n  EuiHorizontalRule,\n  EuiShowFor,\n  EuiHideFor,\n  EuiOutsideClickDetector,\n} from '../../../../src/components';\n\nimport HeaderUserMenu from '../header/header_user_menu';\nimport HeaderSpacesMenu from '../header/header_spaces_menu';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isCollapsed: true,\n      flyoutIsCollapsed: true,\n      flyoutIsAnimating: false,\n      navFlyoutTitle: undefined,\n      navFlyoutContent: [],\n      mobileIsHidden: true,\n      showScrollbar: false,\n      outsideClickDisabled: true,\n      isManagingFocus: false,\n    };\n\n    this.topLinks = [\n      {\n        label: 'Recently viewed',\n        iconType: 'clock',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Recently viewed items',\n        onClick: () => this.expandFlyout(this.recentLinks, 'Recent items'),\n        extraAction: {\n          color: 'subdued',\n          iconType: 'arrowRight',\n          iconSize: 's',\n          'aria-label': 'Expand to view recent apps and objects',\n          onClick: () => this.expandFlyout(this.recentLinks, 'Recent items'),\n          alwaysShow: true,\n        },\n      },\n      {\n        label: 'Favorites',\n        iconType: 'starEmpty',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Favorited items',\n        onClick: () => this.expandFlyout(this.favoriteLinks, 'Favorite items'),\n        extraAction: {\n          color: 'subdued',\n          iconType: 'arrowRight',\n          iconSize: 's',\n          'aria-label': 'Expand to view favorited apps and objects',\n          onClick: () => this.expandFlyout(this.favoriteLinks, 'Favorite items'),\n          alwaysShow: true,\n        },\n      },\n    ];\n\n    this.exploreLinks = [\n      {\n        label: 'Canvas',\n        href: '/#/layout/nav-drawer',\n        iconType: 'canvasApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Canvas',\n        isActive: true,\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pinFilled',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n          alwaysShow: true,\n        },\n      },\n      {\n        label: 'Discover',\n        href: '/#/layout/nav-drawer',\n        iconType: 'discoverApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Discover',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      },\n      {\n        label: 'Visualize',\n        href: '/#/layout/nav-drawer',\n        iconType: 'visualizeApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Visualize',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      },\n      {\n        label: 'Dashboard',\n        href: '/#/layout/nav-drawer',\n        iconType: 'dashboardApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Dashboard',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      },\n      {\n        label: 'Machine learning',\n        href: '/#/layout/nav-drawer',\n        iconType: 'machineLearningApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Machine learning',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      },\n      {\n        label: 'Graph',\n        href: '/#/layout/nav-drawer',\n        iconType: 'graphApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Graph',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      }\n    ];\n\n    this.solutionsLinks = [\n      {\n        label: 'APM',\n        href: '/#/layout/nav-drawer',\n        iconType: 'apmApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'APM',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      },\n      {\n        label: 'Infrastructure',\n        href: '/#/layout/nav-drawer',\n        iconType: 'infraApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Infra',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      },\n      {\n        label: 'Log viewer',\n        href: '/#/layout/nav-drawer',\n        iconType: 'loggingApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Logs',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      },\n      {\n        label: 'Uptime',\n        href: '/#/layout/nav-drawer',\n        iconType: 'upgradeAssistantApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Graph',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      },\n      {\n        label: 'Maps',\n        href: '/#/layout/nav-drawer',\n        iconType: 'gisApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Maps',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      },\n      {\n        label: 'SIEM',\n        href: '/#/layout/nav-drawer',\n        iconType: 'securityAnalyticsApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'SIEM',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'pin',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n        },\n      }\n    ];\n\n    this.adminLinks = [\n      {\n        label: 'Admin',\n        iconType: 'managementApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Admin',\n        onClick: () => this.expandFlyout(this.adminSubLinks, 'Tools and settings'),\n        extraAction: {\n          color: 'subdued',\n          iconType: 'arrowRight',\n          iconSize: 's',\n          'aria-label': 'Pin to top',\n          alwaysShow: true,\n          onClick: () => this.expandFlyout(this.adminSubLinks, 'Tools and settings'),\n        },\n      },\n    ];\n\n    this.adminSubLinks = [\n      {\n        label: 'Dev tools',\n        href: '/#/layout/nav-drawer',\n        iconType: 'devToolsApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Dev tools',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'starEmpty',\n          iconSize: 's',\n          'aria-label': 'Add to favorites',\n        },\n      },\n      {\n        label: 'Stack Monitoring',\n        href: '/#/layout/nav-drawer',\n        iconType: 'monitoringApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Monitoring',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'starEmpty',\n          iconSize: 's',\n          'aria-label': 'Add to favorites',\n        },\n      },\n      {\n        label: 'Stack Management',\n        href: '/#/layout/nav-drawer',\n        iconType: 'managementApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Management',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'starEmpty',\n          iconSize: 's',\n          'aria-label': 'Add to favorites',\n        },\n      },\n    ];\n\n    this.recentLinks = [\n      {\n        label: 'My dashboard',\n        href: '/#/layout/nav-drawer',\n        iconType: 'dashboardApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'My dashboard',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'starEmpty',\n          iconSize: 's',\n          'aria-label': 'Add to favorites',\n        },\n      },\n      {\n        label: 'Workpad with title that wraps',\n        href: '/#/layout/nav-drawer',\n        iconType: 'canvasApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'Workpad with title that wraps',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'starEmpty',\n          iconSize: 's',\n          'aria-label': 'Add to favorites',\n        },\n      },\n      {\n        label: 'My logs',\n        href: '/#/layout/nav-drawer',\n        iconType: 'loggingApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'My logs',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'starEmpty',\n          iconSize: 's',\n          'aria-label': 'Add to favorites',\n        },\n      },\n    ];\n\n    this.favoriteLinks = [\n      {\n        label: 'My workpad',\n        href: '/#/layout/nav-drawer',\n        iconType: 'canvasApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'My workpad',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'starFilled',\n          iconSize: 's',\n          'aria-label': 'Add to favorites',\n          alwaysShow: true,\n        },\n      },\n      {\n        label: 'My logs',\n        href: '/#/layout/nav-drawer',\n        iconType: 'loggingApp',\n        size: 's',\n        style: { color: 'inherit' },\n        'aria-label': 'My logs',\n        extraAction: {\n          color: 'subdued',\n          iconType: 'starFilled',\n          iconSize: 's',\n          'aria-label': 'Add to favorites',\n          alwaysShow: true,\n        },\n      },\n    ];\n  }\n\n  renderLogo() {\n    return (\n      <EuiHeaderLogo\n        iconType=\"logoKibana\"\n        href=\"/#/layout/nav-drawer\"\n        aria-label=\"Goes to home\"\n      />\n    );\n  }\n\n  renderMenuTrigger() {\n    return (\n      <EuiHeaderSectionItemButton\n        aria-label=\"Open nav\"\n        onClick={this.toggleOpen}\n      >\n        <EuiIcon type=\"apps\" href=\"#\" size=\"m\" />\n      </EuiHeaderSectionItemButton>\n    );\n  }\n\n  renderBreadcrumbs() {\n    const breadcrumbs = [\n      {\n        text: 'Management',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked management');\n        },\n        'data-test-subj': 'breadcrumbsAnimals',\n        className: 'customClass'\n      },\n      {\n        text: 'Truncation test is here for a really long item',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked truncation test');\n        }\n      },\n      {\n        text: 'hidden',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked hidden');\n        }\n      },\n      {\n        text: 'Users',\n        href: '#',\n        onClick: e => {\n          e.preventDefault();\n          console.log('You clicked users');\n        }\n      },\n      {\n        text: 'Create'\n      }\n    ];\n\n    return (\n      <EuiHeaderBreadcrumbs\n        breadcrumbs={breadcrumbs}\n      />\n    );\n  }\n\n  timeoutID;\n\n  toggleOpen = () => {\n    this.setState({\n      mobileIsHidden: !this.state.mobileIsHidden\n    });\n\n    setTimeout(() => {\n      this.setState({\n        outsideClickDisabled: this.state.mobileIsHidden ? true : false,\n      });\n    }, 350);\n  };\n\n  expandDrawer = () => {\n    this.setState({ isCollapsed: false });\n\n    setTimeout(() => {\n      this.setState({\n        showScrollbar: true,\n      });\n    }, 350);\n\n    // This prevents the drawer from collapsing when tabbing through children\n    // by clearing the timeout thus cancelling the onBlur event (see focusOut).\n    // This means isManagingFocus remains true as long as a child element\n    // has focus. This is the case since React bubbles up onFocus and onBlur\n    // events from the child elements.\n    clearTimeout(this.timeoutID);\n\n    if (!this.state.isManagingFocus) {\n      this.setState({\n        isManagingFocus: true,\n      });\n    }\n  };\n\n  collapseDrawer = () => {\n    this.setState({\n      flyoutIsAnimating: false,\n    });\n\n    setTimeout(() => {\n      this.setState({\n        isCollapsed: true,\n        flyoutIsCollapsed: true,\n        mobileIsHidden: true,\n        showScrollbar: false,\n        outsideClickDisabled: true,\n      });\n    }, 350);\n\n    // Scrolls the menu and flyout back to top when the nav drawer collapses\n    setTimeout(() => {\n      document.getElementById('navDrawerMenu').scrollTop = 0;\n      document.getElementById('navDrawerFlyout').scrollTop = 0;\n    }, 300);\n  };\n\n  focusOut = () => {\n    // This collapses the drawer when no children have focus (i.e. tabbed out).\n    // In other words, if focus does not bubble up from a child element, then\n    // the drawer will collapse. See the corresponding block in expandDrawer\n    // (called by onFocus) which cancels this operation via clearTimeout.\n    this.timeoutID = setTimeout(() => {\n      if (this.state.isManagingFocus) {\n        this.setState({\n          isManagingFocus: false,\n        });\n\n        this.collapseDrawer();\n      }\n    }, 0);\n  }\n\n  expandFlyout = (links, title) => {\n    const content = links;\n\n    this.setState(prevState => ({\n      flyoutIsCollapsed: prevState.navFlyoutTitle === title ? !this.state.flyoutIsCollapsed : false,\n    }));\n\n    this.setState({\n      flyoutIsAnimating: true,\n      navFlyoutTitle: title,\n      navFlyoutContent: content\n    });\n  };\n\n  collapseFlyout = () => {\n    this.setState({ flyoutIsAnimating: true });\n\n    setTimeout(() => {\n      this.setState({\n        flyoutIsCollapsed: true,\n        navFlyoutTitle: null,\n        navFlyoutContent: null\n      });\n    }, 250);\n  };\n\n  render() {\n    const {\n      isCollapsed,\n      flyoutIsCollapsed,\n      flyoutIsAnimating,\n      navFlyoutTitle,\n      navFlyoutContent,\n      mobileIsHidden,\n      showScrollbar,\n      outsideClickDisabled,\n    } = this.state;\n\n    return (\n      <Fragment>\n        <div style={{ position: 'relative' }}>\n          <EuiHeader>\n            <EuiHeaderSection grow={false}>\n              <EuiShowFor sizes={['xs', 's']}>\n                <EuiHeaderSectionItem border=\"right\">\n                  {this.renderMenuTrigger()}\n                </EuiHeaderSectionItem>\n              </EuiShowFor>\n              <EuiHeaderSectionItem border=\"right\">{this.renderLogo()}</EuiHeaderSectionItem>\n              <EuiHeaderSectionItem border=\"right\">\n                <HeaderSpacesMenu />\n              </EuiHeaderSectionItem>\n            </EuiHeaderSection>\n\n            {this.renderBreadcrumbs()}\n\n            <EuiHeaderSection side=\"right\">\n              <EuiHeaderSectionItem>\n                <HeaderUserMenu />\n              </EuiHeaderSectionItem>\n            </EuiHeaderSection>\n          </EuiHeader>\n          <EuiOutsideClickDetector\n            onOutsideClick={() => this.collapseDrawer()}\n            isDisabled={outsideClickDisabled}\n          >\n            <EuiNavDrawer\n              isCollapsed={isCollapsed}\n              flyoutIsCollapsed={flyoutIsCollapsed}\n              flyoutIsAnimating={flyoutIsAnimating}\n              onMouseOver={this.expandDrawer}\n              onFocus={this.expandDrawer}\n              onBlur={this.focusOut}\n              onMouseLeave={this.collapseDrawer}\n              mobileIsHidden={mobileIsHidden}\n              showScrollbar={showScrollbar}\n              style={{ position: 'absolute' }} // This is for the embedded docs example only\n            >\n              <EuiNavDrawerMenu id=\"navDrawerMenu\">\n                <EuiListGroup listItems={this.topLinks} />\n                <EuiHorizontalRule margin=\"none\" />\n                <EuiListGroup listItems={this.exploreLinks} />\n                <EuiHorizontalRule margin=\"none\" />\n                <EuiListGroup listItems={this.solutionsLinks} />\n                <EuiHorizontalRule margin=\"none\" />\n                <EuiListGroup listItems={this.adminLinks} />\n              </EuiNavDrawerMenu>\n              <EuiNavDrawerFlyout\n                id=\"navDrawerFlyout\"\n                title={navFlyoutTitle}\n                isCollapsed={flyoutIsCollapsed}\n                listItems={navFlyoutContent}\n                onMouseLeave={this.collapseFlyout}\n                wrapText={true}\n              />\n            </EuiNavDrawer>\n          </EuiOutsideClickDetector>\n          <EuiPage style={{ minHeight: '600px' }}>\n            <EuiPageBody style={{ marginLeft: '64px' }}>\n              <EuiHideFor sizes={['xs', 's']}>\n                <EuiPageHeader>\n                  <EuiPageHeaderSection>\n                    <EuiTitle size=\"l\">\n                      <h1>Page title</h1>\n                    </EuiTitle>\n                  </EuiPageHeaderSection>\n                </EuiPageHeader>\n                <EuiPageContent>\n                  <EuiPageContentHeader>\n                    <EuiPageContentHeaderSection>\n                      <EuiTitle>\n                        <h2>Content title</h2>\n                      </EuiTitle>\n                    </EuiPageContentHeaderSection>\n                  </EuiPageContentHeader>\n                  <EuiPageContentBody>\n                    Body content\n                  </EuiPageContentBody>\n                </EuiPageContent>\n              </EuiHideFor>\n            </EuiPageBody>\n          </EuiPage>\n        </div>\n      </Fragment>\n    );\n  }\n}\n"