module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiDatePicker,\n  EuiSpacer,\n  EuiFormRow,\n} from '../../../../src/components';\n\nexport default class extends Component {\n\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      startDate: null,\n    };\n\n    this.handleChange = this.handleChange.bind(this);\n  }\n\n  handleChange(date) {\n    this.setState({\n      startDate: date\n    });\n  }\n\n  render() {\n    const errors = [\n      'Here\\'s an example of an error',\n      'You might have more than one error, so pass an array.',\n    ];\n\n    return (\n      <div>\n        <EuiDatePicker\n          showTimeSelect\n          selected={this.state.startDate}\n          onChange={this.handleChange}\n          placeholder=\"Placeholder text\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiDatePicker\n          showTimeSelect\n          selected={this.state.startDate}\n          onChange={this.handleChange}\n          disabled\n          placeholder=\"Disabled\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiDatePicker\n          showTimeSelect\n          selected={this.state.startDate}\n          onChange={this.handleChange}\n          isLoading\n          placeholder=\"Loading\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiDatePicker\n          showTimeSelect\n          selected={this.state.startDate}\n          onChange={this.handleChange}\n          isLoading\n          disabled\n          placeholder=\"Loading and disabled\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFormRow\n          label=\"Form row validation\"\n          isInvalid\n          error={errors}\n        >\n          <EuiDatePicker\n            showTimeSelect\n            isInvalid\n            selected={this.state.startDate}\n            onChange={this.handleChange}\n            placeholder=\"Example of an error\"\n          />\n        </EuiFormRow>\n      </div>\n    );\n  }\n}\n"