module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiBadge,\n  EuiButton,\n  EuiFocusTrap,\n  EuiPanel,\n  EuiSpacer,\n  EuiText\n} from '../../../../src/components';\n\nimport FormExample from '../form_layouts/form_compressed';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isDisabled: false,\n    };\n  }\n\n  toggleDisabled = () => {\n    this.setState(prevState => ({\n      isDisabled: !prevState.isDisabled,\n    }));\n  }\n\n  render() {\n    const { isDisabled } = this.state;\n\n    return (\n      <div>\n        <EuiBadge>Trap is {isDisabled ? 'disabled' : 'enabled'}</EuiBadge>\n        <EuiSpacer size=\"s\" />\n        <EuiFocusTrap\n          disabled={isDisabled}\n        >\n          <EuiPanel>\n            <FormExample />\n\n            <EuiSpacer size=\"m\" />\n\n            <EuiButton onClick={this.toggleDisabled}>\n              {`${!isDisabled ? 'Disable' : 'Enable'} Focus Trap`}\n            </EuiButton>\n          </EuiPanel>\n\n        </EuiFocusTrap>\n\n        <EuiSpacer size=\"l\" />\n\n        <EuiText>\n          The button below is not focusable by keyboard as long as the focus trap is enabled.\n        </EuiText>\n\n        <EuiButton onClick={() => alert('External event triggered')}>\n          External Focusable Element\n        </EuiButton>\n      </div>\n    );\n  }\n}\n"