module.exports = "import React, {\n  Component,\n  Fragment,\n} from 'react';\n\nimport {\n  EuiFieldNumber,\n  EuiSpacer,\n  EuiText,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      value: '',\n    };\n  }\n\n  onChange = e => {\n    const sanitizedValue = parseInt(e.target.value, 10);\n    this.setState({\n      value: isNaN(sanitizedValue) ? '' : sanitizedValue,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiFieldNumber\n          placeholder=\"Placeholder text\"\n          value={this.state.value}\n          onChange={this.onChange}\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldNumber\n          placeholder=\"Disabled\"\n          value={this.state.value}\n          onChange={this.onChange}\n          disabled\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldNumber\n          placeholder=\"Loading\"\n          value={this.state.value}\n          onChange={this.onChange}\n          isLoading\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldNumber\n          placeholder=\"Loading and disabled\"\n          value={this.state.value}\n          onChange={this.onChange}\n          disabled\n          isLoading\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldNumber\n          placeholder=\"Read-only\"\n          value={this.state.value}\n          onChange={this.onChange}\n          readOnly\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldNumber\n          placeholder=\"Compressed\"\n          value={this.state.value}\n          onChange={this.onChange}\n          compressed\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldNumber\n          style={{ textAlign: 'right' }}\n          append={<EuiText size=\"xs\"><strong>%</strong></EuiText>}\n          placeholder=\"0 - 100\"\n          value={this.state.value}\n          onChange={this.onChange}\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n      </Fragment>\n    );\n  }\n}\n"