module.exports = "import React from 'react';\n\nimport {\n  EuiFlexGrid,\n  EuiFlexItem,\n  EuiIcon,\n  EuiPanel,\n  EuiText,\n} from '../../../../src/components';\n\nconst iconTypes = [\n  'addDataApp',\n  'advancedSettingsApp',\n  'apmApp',\n  'auditbeatApp',\n  'canvasApp',\n  'codeApp',\n  'consoleApp',\n  'crossClusterReplicationApp',\n  'dashboardApp',\n  'devToolsApp',\n  'discoverApp',\n  'emsApp',\n  'filebeatApp',\n  'gisApp',\n  'graphApp',\n  'grokApp',\n  'heartbeatApp',\n  'indexManagementApp',\n  'indexPatternApp',\n  'indexRollupApp',\n  'infraApp',\n  'loggingApp',\n  'machineLearningApp',\n  'managementApp',\n  'metricbeatApp',\n  'monitoringApp',\n  'notebookApp',\n  'packetbeatApp',\n  'pipelineApp',\n  'reportingApp',\n  'savedObjectsApp',\n  'searchProfilerApp',\n  'securityAnalyticsApp',\n  'securityApp',\n  'spacesApp',\n  'sqlApp',\n  'timelionApp',\n  'upgradeAssistantApp',\n  'uptimeApp',\n  'usersRolesApp',\n  'visualizeApp',\n  'watchesApp',\n];\n\nexport default () => (\n  <EuiFlexGrid columns={4}>\n    {\n      iconTypes.map(iconType => (\n        <EuiFlexItem\n          className=\"guideDemo__icon\"\n          key={iconType}\n          style={{ width: '200px' }}\n        >\n          <EuiPanel>\n            <EuiIcon\n              type={iconType}\n              size=\"xl\"\n            />\n            <EuiText size=\"s\">\n              <p>{iconType}</p>\n            </EuiText>\n          </EuiPanel>\n        </EuiFlexItem>\n      ))\n    }\n  </EuiFlexGrid>\n);\n"