module.exports = "import React, { Fragment } from 'react';\n\nimport {\n  EuiFlexGrid,\n  EuiFlexItem,\n  EuiPanel,\n  EuiText,\n  EuiToken,\n  EuiSpacer,\n} from '../../../../src/components';\n\nconst tokens = [\n  'tokenAnnotation',\n  'tokenArray',\n  'tokenBoolean',\n  'tokenClass',\n  'tokenConstant',\n  'tokenElement',\n  'tokenEnum',\n  'tokenEnumMember',\n  'tokenEvent',\n  'tokenException',\n  'tokenField',\n  'tokenFunction',\n  'tokenInterface',\n  'tokenKey',\n  'tokenMethod',\n  'tokenNull',\n  'tokenNumber',\n  'tokenObject',\n  'tokenOperator',\n  'tokenPackage',\n  'tokenParameter',\n  'tokenProperty',\n  'tokenString',\n  'tokenStruct',\n  'tokenVariable',\n  'tokenFile',\n  'tokenSymbol',\n  'tokenRepo'\n];\n\nexport default () => (\n  <Fragment>\n    <EuiFlexGrid columns={4}>\n      {\n        tokens.map(token => (\n          <EuiFlexItem\n            className=\"guideDemo__icon\"\n            key={token}\n          >\n            <EuiPanel>\n              <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '8px' }}>\n                <EuiToken iconType={token}/>\n              </div>\n              <EuiText size=\"s\">\n                <p>{token}</p>\n              </EuiText>\n            </EuiPanel>\n          </EuiFlexItem>\n        ))\n      }\n    </EuiFlexGrid>\n\n    <EuiSpacer />\n\n    <EuiFlexGrid columns={4}>\n      <EuiFlexItem\n        className=\"guideDemo__icon\"\n      >\n        <EuiPanel>\n          <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '8px' }}>\n            <EuiToken\n              iconType=\"tokenEvent\"\n              size=\"m\"\n              displayOptions={{\n                color: 'tokenTint10',\n                shape: 'square',\n                fill: true,\n              }}\n            />\n          </div>\n          <EuiText size=\"s\">\n            <p>A custom token</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n      <EuiFlexItem\n        className=\"guideDemo__icon\"\n      >\n        <EuiPanel>\n          <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '8px' }}>\n            <EuiToken\n              iconType=\"visMapCoordinate\"\n              displayOptions={{\n                color: 'tokenTint05',\n                shape: 'circle',\n              }}\n            />\n          </div>\n          <EuiText size=\"s\">\n            <p>A custom token</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n      <EuiFlexItem\n        className=\"guideDemo__icon\"\n      >\n        <EuiPanel>\n          <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '8px' }}>\n            <EuiToken\n              iconType=\"tokenElement\"\n              size=\"l\"\n              displayOptions={{\n                color: 'tokenTint07',\n                shape: 'rectangle',\n                hideBorder: true\n              }}\n            />\n          </div>\n          <EuiText size=\"s\">\n            <p>A custom token</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n    </EuiFlexGrid>\n  </Fragment>\n);\n"